import React, { useEffect, useState } from "react";
import {
  MapContainer,
  TileLayer,
  CircleMarker,
  Popup,
  Circle,
  useMap,
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

// Componente para ajustar la vista del mapa dinámicamente
const ChangeView = ({ coordenadas }) => {
  const map = useMap();

  useEffect(() => {
    if (coordenadas) {
      map.setView([coordenadas.lat, coordenadas.lng], 7); // Centra el mapa
    }
  }, [coordenadas, map]);

  return null;
};

// Componente para controlar el mapa y sus tiles
const MapContent = ({ coordenadas, theme, circleScale, opacity }) => {
  const map = useMap();
  
  // Efecto para actualizar las capas del mapa cuando cambia el tema
  useEffect(() => {
    // Elimina todas las capas base existentes
    map.eachLayer((layer) => {
      if (layer instanceof L.TileLayer) {
        map.removeLayer(layer);
      }
    });
    
    // Añade la nueva capa según el tema
    const tileUrl = theme === "dark"
      ? "https://tiles.stadiamaps.com/tiles/alidade_smooth_dark/{z}/{x}/{y}{r}.png"
      : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png";
      
    L.tileLayer(tileUrl).addTo(map);
  }, [theme, map]);

  return (
    <>
      <ChangeView coordenadas={coordenadas} />
      
      {coordenadas && (
        <>
          <CircleMarker
            center={[coordenadas.lat, coordenadas.lng]}
            radius={10}
            color="red"
            fillColor="red"
            fillOpacity={0.7}
          >
            <Popup>
              <b>Ubicación del Sismo</b> <br />
              Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
            </Popup>
          </CircleMarker>

          {/* Círculo expandible */}
          <Circle
            center={[coordenadas.lat, coordenadas.lng]}
            radius={circleScale * 50000}
            color="red"
            fillColor="red"
            fillOpacity={opacity}
            stroke={false}
          />
        </>
      )}
    </>
  );
};

const MapaMexico = ({ coordenadas, theme }) => {
  const [circleScale, setCircleScale] = useState(1);
  const [opacity, setOpacity] = useState(0.6);

  // Manejo del efecto de expansión del círculo
  useEffect(() => {
    if (!coordenadas) return;

    setCircleScale(1); 
    setOpacity(0.6);

    const interval = setInterval(() => {
      setCircleScale((prev) => prev + 0.05);
      setOpacity((prev) => Math.max(prev - 0.01, 0));

      if (circleScale > 3 || opacity <= 0) {
        setCircleScale(1);
        setOpacity(0.6);
      }
    }, 50);

    return () => clearInterval(interval); 
  }, [coordenadas, circleScale, opacity]);

  // Importamos Leaflet de manera dinámica para evitar errores en SSR
  useEffect(() => {
    // Cargar Leaflet globalmente
    if (!window.L) {
      window.L = require('leaflet');
    }
  }, []);

  return (
    <MapContainer
      center={[23.6345, -102.5528]} // Centro de México
      zoom={5}
      style={{ height: "100vh", width: "100%" }}
      whenCreated={(mapInstance) => {
        // Este callback se ejecuta cuando el mapa se crea inicialmente
        console.log("Mapa creado");
      }}
    >
      {/* No incluimos TileLayer aquí, lo manejaremos dinámicamente */}
      <MapContent 
        coordenadas={coordenadas} 
        theme={theme} 
        circleScale={circleScale} 
        opacity={opacity} 
      />
    </MapContainer>
  );
};

export default MapaMexico;
